// Generates docs/mcp-tools.md from the live tool definitions so documentation cannot drift from the code.
import fs from "node:fs";
import { z } from "zod";
import { TOOLS } from "@repo-scout/mcp";

const lines = [
  "# MCP tool reference",
  "",
  "_Generated by `pnpm docs:gen` from the Zod schemas in `packages/mcp/src/tools.ts`. Do not edit by hand._",
  "",
  "All tools return the same envelope (`structuredContent`) plus a concise Markdown text rendering:",
  "",
  "```json",
  JSON.stringify(
    {
      ok: true,
      tool: "scout_search",
      summary: "…",
      data: "{…tool specific…}",
      warnings: [],
      error: null,
      meta: { generatedAt: "ISO-8601", durationMs: 0, version: "0.1.0", untrustedContentNotice: "…" },
    },
    null,
    2,
  ),
  "```",
  "",
  "On failure `ok=false`, `isError=true` and `error = { code, message, hint? }` with codes `INVALID_INPUT | NOT_FOUND | RATE_LIMITED | PROVIDER_ERROR | PROVIDER_UNAVAILABLE | NETWORK | TIMEOUT | SECURITY_BLOCKED | CONFIG | DATABASE | INTERNAL`.",
  "",
  "| Tool | Read-only | Purpose |",
  "|---|---|---|",
  ...TOOLS.map(
    (t) =>
      `| \`${t.name}\` | ${t.readOnly ? "yes" : "**no (local cache deletion)**"} | ${t.description.split(". ")[0]!.replace(/\|/g, "\\|")}. |`,
  ),
  "",
];
for (const t of TOOLS) {
  const schema = z.toJSONSchema(z.object(t.input as z.ZodRawShape)) as any;
  lines.push(
    `## \`${t.name}\``,
    "",
    t.description,
    "",
    "| Parameter | Type | Required | Description |",
    "|---|---|---|---|",
  );
  for (const [k, v] of Object.entries<any>(schema.properties ?? {})) {
    const type = v.enum
      ? v.enum.map((e: string) => `\`${e}\``).join(" \\| ")
      : v.type === "array"
        ? `${v.items?.enum ? "(" + v.items.enum.join("|") + ")" : (v.items?.type ?? "any")}[]`
        : v.type;
    lines.push(
      `| \`${k}\` | ${type} | ${(schema.required ?? []).includes(k) ? "yes" : "no"} | ${(v.description ?? "").replace(/\|/g, "\\|")} |`,
    );
  }
  if (!Object.keys(schema.properties ?? {}).length) lines.push("| _(none)_ | | | |");
  lines.push("");
}
fs.writeFileSync("docs/mcp-tools.md", lines.join("\n"));
console.log(`wrote docs/mcp-tools.md (${TOOLS.length} tools)`);
